import {readOwnership,readHistory,owner,eligibility} from './game.js';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let config,territories,geography,map,layers=new Map(),ownership={},history=[],selected=null,revealed=new Set(),remember=false,busy=false,lastSuccess=null;
const storageKey='boston-showdown-reveals-v1';
const json=async url=>{const r=await fetch(url);if(!r.ok)throw Error('Could not load '+url);return r.json();};
function teamColor(id){return config.teams.find(t=>t.id===id)?.color||'#a1b298';}
function stateText(id){const s=ownership[id];return s?.locked?`${s.locked} · Locked ◆`:s?.claimed?`${s.claimed} · Claimed`:'Unclaimed';}
function paint(){for(const [id,layer] of layers){const state=ownership[id]||{},who=owner(state);layer.setStyle({color:id===selected?.id?'#132e2a':who?teamColor(who):'#657b61',weight:id===selected?.id?3:1.5,fillColor:teamColor(who),fillOpacity:who?(state.locked?.72:.32):.2,dashArray:who&&!state.locked?'5 4':null});}renderScores();renderList();renderGrid();if(selected)renderDetail();}
function renderScores(){const scores=config.teams.map(t=>{const records=Object.values(ownership).filter(s=>owner(s)===t.id);return `<div class="score" style="--team:${esc(t.color)}"><span class="dot"></span><div><strong>${esc(t.id)} TEAM</strong><small>${records.filter(s=>s.locked).length} locked · ${records.filter(s=>!s.locked).length} claimed</small></div><span class="number">${records.length}</span></div>`;});const free=territories.filter(t=>!owner(ownership[t.id])).length;scores.push(`<div class="score"><span class="dot"></span><div><strong>UP FOR GRABS</strong><small>Territory count · draft scoring</small></div><span class="number">${free}</span></div>`);$('#scores').innerHTML=scores.join('');}
function renderList(){if(selected)return;const query=$('#territory-search').value.toLowerCase();const items=territories.filter(t=>t.name.toLowerCase().includes(query));$('#territory-list').innerHTML=items.length?items.map(t=>`<button class="territory-row" data-id="${t.id}"><span>${esc(t.name)}</span><small>${esc(stateText(t.id))} ↗</small></button>`).join(''):'<p>No matching territories.</p>';}
function renderGrid(){$('#territory-grid').innerHTML=territories.map((t,i)=>`<button class="territory-card" data-id="${t.id}"><small>${String(i+1).padStart(2,'0')} / ${esc(t.kind.toUpperCase())}</small><h3>${esc(t.name)}</h3><span class="chip">${esc(stateText(t.id))}</span></button>`).join('');}
function showList(){selected=null;$('#territory-panel').innerHTML='<div class="eyebrow">CHOOSE YOUR NEXT STOP</div><h2>Where to?</h2><p>Tap a territory or pick one below. Challenge details stay hidden until you reveal the card.</p><label for="territory-search">Find a territory</label><input id="territory-search" type="search" placeholder="Search neighborhoods & cities"><div id="territory-list"></div>';$('#territory-search').addEventListener('input',renderList);paint();}
function renderDetail(){const t=selected;const google='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(t.name+(t.kind==='Municipality'?', Massachusetts':', Boston MA'));$('#territory-panel').innerHTML=`<button class="back" id="back">← ALL TERRITORIES</button><div class="eyebrow" style="margin-top:30px">${esc(t.kind.toUpperCase())}</div><h2 class="selected-name">${esc(t.name)}</h2><span class="chip">${esc(stateText(t.id))}</span><p>Leave transit and reach a public outdoor location inside this territory to claim it. Complete its challenge to lock it.</p><div class="panel-actions"><button class="button" id="reveal">Reveal challenge →</button><a class="button light" href="${google}" target="_blank" rel="noopener">Check Google Maps ↗</a><button class="button light" id="edit-sheet">Record in game sheet ↗</button></div><p class="detail-note">${esc(t.boundaryNote)}</p>`;$('#back').onclick=showList;$('#reveal').onclick=()=>openGate(t);$('#edit-sheet').onclick=openSheet;}
function select(id){selected=territories.find(t=>t.id===id);setView('board');paint();const layer=layers.get(id);if(layer)map.fitBounds(layer.getBounds(),{padding:[35,35],maxZoom:14});if(innerWidth<650)$('#territory-panel').scrollIntoView({behavior:'smooth',block:'start'});}
function setView(view){for(const v of ['board','territories','rules'])$('#'+v+'-view').hidden=v!==view;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='board')setTimeout(()=>map?.invalidateSize(),20);}
function openSheet(){if(config.sheetUrl){window.open(config.sheetUrl,'_blank','noopener');}else{$('#challenge-content').innerHTML='<div class="reveal-gate"><div class="eyebrow">SETUP / GOOGLE SHEETS</div><h2>Your shared game record</h2><p>The live sheet is not connected yet. Import the workbook into Google Sheets, then send its editable link and published Ownership and History CSV links.</p><p><a class="button" href="templates/Boston-Showdown-Game-Template.xlsx" download>Download full spreadsheet template ↓</a></p><p>The workbook includes team dropdowns, challenge tracking, and warnings. Demo ownership and challenge cards on this site are for testing the interface.</p><p><a href="templates/Ownership.csv" download>Ownership CSV only ↓</a></p><p><a href="templates/Team-history.csv" download>History CSV only ↓</a></p></div>';$('#challenge-dialog').showModal();}}
function openGate(t){const dialog=$('#challenge-dialog');$('#challenge-content').innerHTML=`<div class="reveal-gate"><div class="eyebrow">CHALLENGE ENVELOPE / ${esc(t.name.toUpperCase())}</div><h2>Ready to open it?</h2><p>Keep the challenge hidden until you arrive. Your team can work on one challenge at a time.</p><label for="team">Your team</label><select id="team">${config.teams.map(team=>`<option>${esc(team.id)}</option>`).join('')}</select><label><input type="checkbox" id="arrived"> We have left transit and reached a public outdoor location inside this territory.</label><label><input type="checkbox" id="resolved"> We have resolved our previous challenge and will record this reveal in our team sheet.</label><p id="gate-warning" class="inline-error" role="status"></p><button class="button" id="open-envelope" disabled>Open challenge card →</button><p class="detail-note">${config.historyCsvUrl?'Eligibility checked against the last loaded sheet.':'Honor system: shared challenge history is not connected yet.'} Opening another challenge ends retries on the previous one.</p></div>`;
  const savedButton=document.createElement('button');savedButton.className='button light';savedButton.textContent='View previously revealed card (reference only)';savedButton.onclick=()=>showCard(t,$('#team').value,true);$('#open-envelope').after(savedButton);
  const check=()=>{const result=eligibility(history,$('#team').value,t.id,t.retryable);const locked=ownership[t.id]?.locked;const blocked=locked&&locked!==$('#team').value;savedButton.hidden=!revealed.has($('#team').value+'/'+t.id);$('#gate-warning').textContent=blocked?'This territory is locked by another team. It cannot be stolen.':result.message||'';$('#open-envelope').disabled=!$('#arrived').checked||!$('#resolved').checked||!result.allowed||blocked;};for(const id of ['team','arrived','resolved'])$('#'+id).onchange=check;check();$('#open-envelope').onclick=()=>showCard(t,$('#team').value);dialog.showModal();}
async function showCard(t,team,reference=false){const content=$('#challenge-content');content.innerHTML='<div class="reveal-gate"><p role="status">Opening your challenge…</p></div>';try{const r=await fetch(t.challengePath);if(!r.ok)throw Error('The challenge card could not be loaded.');const markdown=await r.text();if(!reference){if(!reference){revealed.add(team+'/'+t.id);persist();}}const lines=markdown.trim().split(/\r?\n/);const title=lines.shift().replace(/^#\s*/,'');const body=lines.join('\n').replace(/^(## .+)$/gm,'\n$1\n').split(/\n\s*\n/).map(part=>part.trim()).filter(Boolean).map(part=>part.startsWith('## ')?'<h3>'+esc(part.slice(3))+'</h3>':'<p'+(part.startsWith('DEMO')?' class="demo"':'')+'>'+esc(part)+'</p>').join('');content.innerHTML=`<div class="challenge-banner"><span>${esc(t.name.toUpperCase())} / CHALLENGE CARD</span><h2>${esc(title)}</h2></div><div class="challenge-body">${body}<span class="chip">${t.retryable?'Retryable until your next reveal':'One attempt only'}</span>${reference?'<p><strong>Reference only.</strong> Viewing this card does not reactivate it or allow another attempt.</p>':`${reference?'<p><strong>Reference only.</strong> Viewing this card does not reactivate it or allow another attempt.</p>':`<p><strong>Record now:</strong> ${esc(team)} → ${esc(t.name)} → next reveal order → Active. Record Succeeded, Failed, or Abandoned before revealing another card.</p>`}`}<button class="button" id="record">Open game sheet ↗</button><p class="detail-note">${remember?'This reveal is remembered on this device.':'This reveal will not be saved on this device after this session.'}</p></div>`;$('#record').onclick=()=>{if(config.sheetUrl)openSheet();else{content.querySelector('.detail-note').textContent='No sheet connected. Use the templates from the Open game sheet button after closing this card.';}};}catch(e){content.innerHTML='<div class="reveal-gate"><h2>Card unavailable</h2><p>'+esc(e.message)+'</p></div>';}}
function persist(){if(!remember)return;try{localStorage.setItem(storageKey,JSON.stringify([...revealed]));}catch{$('#sync-status').textContent='Device storage unavailable. Reveals remain in this session only.';}}
async function refresh(){if(busy||!config.ownershipCsvUrl)return;busy=true;$('#refresh').disabled=true;$('#sync-status').textContent='Reading the shared game sheet…';try{const urls=[config.ownershipCsvUrl,...(config.historyCsvUrl?[config.historyCsvUrl]:[])];const texts=await Promise.all(urls.map(async url=>{const r=await fetch(url,{cache:'no-store',signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('Sheet fetch failed ('+r.status+')');return r.text();}));const next=readOwnership(texts[0],territories,config.teams);const nextHistory=texts[1]?readHistory(texts[1],territories,config.teams):[];ownership=next;history=nextHistory;lastSuccess=new Date();paint();$('#sync-status').textContent='Sheet updated '+lastSuccess.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'})+' · refresh every '+config.refreshSeconds+'s';}catch(e){$('#sync-status').textContent='Sheet unavailable: '+e.message+(lastSuccess?' · retaining last update from '+lastSuccess.toLocaleTimeString():' · no live game data loaded');}finally{busy=false;$('#refresh').disabled=false;}}
async function init(){try{[config,territories,geography]=await Promise.all([json('config.json'),json('data/territories.json'),json('data/territories.geojson')]);config.refreshSeconds=Math.max(15,Number(config.refreshSeconds)||30);if(!config.teams?.length||config.teams.some(t=>!/^#[a-f0-9]{6}$/i.test(t.color)))throw Error('Invalid team configuration');for(const t of territories)ownership[t.id]={claimed:'',locked:''};if(!config.ownershipCsvUrl){ownership['back-bay']={claimed:'Blue',locked:'Blue'};ownership['cambridge']={claimed:'Red',locked:''};ownership['south-end']={claimed:'Blue',locked:'Red'};}
  map=L.map('map',{scrollWheelZoom:true,zoomSnap:.25}).setView([42.34,-71.08],11);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);const geo=L.geoJSON(geography,{onEachFeature:(f,layer)=>{layers.set(f.properties.id,layer);layer.bindTooltip(f.properties.name,{sticky:true});layer.on('click',()=>select(f.properties.id));}}).addTo(map);$('#fit').onclick=()=>map.fitBounds(geo.getBounds(),{padding:[15,15]});map.fitBounds(geo.getBounds(),{padding:[15,15]});
  document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.addEventListener('click',e=>{const item=e.target.closest('[data-id]');if(item)select(item.dataset.id);});$('#territory-search').oninput=renderList;$('#sheet-button').onclick=openSheet;$('#refresh').onclick=refresh;$('.close').onclick=()=>$('#challenge-dialog').close();$('#remember').onchange=e=>{remember=e.target.checked;if(remember)persist();else{try{localStorage.removeItem(storageKey);}catch{}}}; // No storage read/write unless the player opts in.
  $('#remember').onchange=e=>{remember=e.target.checked;if(remember){try{const saved=JSON.parse(localStorage.getItem(storageKey)||'[]');if(Array.isArray(saved))saved.forEach(v=>revealed.add(v));}catch{}persist();}else{try{localStorage.removeItem(storageKey);}catch{}}};paint();if(config.ownershipCsvUrl){await refresh();setInterval(refresh,config.refreshSeconds*1000);}else $('#refresh').disabled=true;
}catch(e){$('#sync-status').textContent='Setup error: '+e.message;}}
init();
